// OUR ICONS. Each is a small drawing in a 24 x 24 box, shaded by one shared style (glossy: light from the
// upper left, strong highlights, a dark edge). Add an icon by adding an entry to ICONS; anything the
// interface asks for that is not here yet shows as a brass token with two letters.
// Entries marked `placeholder: true` are quick drawings meant to be replaced: edit the entry, or
// REPLACE ANY ICON WITHOUT CODE: put `<id>.svg` (any viewBox, square) in apps/web/icons/ and add the
// id to apps/web/icons/index.json (a JSON list, e.g. ["coal", "iron"]); the file then wins over the
// drawing here (js/kit.js loads the list once at start). ICON_ALIAS (end of file) maps other names the
// game uses to a drawing. See every icon with its id at /dev/icons.html.
// ---------------------------------------------------------------- palette (mid, light, dark)
const PAL = {
  gold: ['#e6c41c', '#fff48a', '#8a6808'], olive: ['#b8a020', '#f2e468', '#5c4c08'], red: ['#c4281c', '#ff8a6a', '#6a100a'],
  orange: ['#d98a2c', '#ffc878', '#7c4008'], grey: ['#9c968a', '#dcd6c8', '#4c4840'], white: ['#ecebe4', '#ffffff', '#a8a498'],
  cream: ['#e4dcc0', '#fffbe8', '#989070'], brown: ['#a8662c', '#e0a060', '#553010'], green: ['#6aa82c', '#b8e870', '#2c5410'],
  lav: ['#9aa2e0', '#dce0ff', '#48508c'], steel: ['#b4bcc4', '#f6fafc', '#5a646e'], ink: ['#2c2622', '#7a7068', '#0a0806'],
  pink: ['#e6c6b6', '#fff2ea', '#a07666'], amber: ['#e9a416', '#ffe27a', '#8a4a04'],
  blue: ['#2e5fa8', '#7fb0f0', '#12305c'], khaki: ['#b8a878', '#e8dcb0', '#5c5230'], lime: ['#c5d74e', '#e8f0a8', '#6e7a28'],   // batch 1 (2026-10-07)
};
// The alert glow is a layer UNDER an icon drawn by the page, not part of the drawing: one halo colour per alert.
const GLOW = { rebels: '#ff3a2a', election: '#4ce156', reform: '#4ce156', crisis: '#f7ba66' };
const LINE = '#170e07';
const KINDS = { 1: 'A. Soft light', 2: 'B. Glossy', 3: 'C. Cut planes' };
function defs(kind) {
  let s = '<defs>';
  for (const [k, c] of Object.entries(PAL)) {
    if (kind === 1) s += `<linearGradient id="g-${k}" x1=".1" y1="0" x2=".9" y2="1"><stop offset="0" stop-color="${c[1]}"/><stop offset=".5" stop-color="${c[0]}"/><stop offset="1" stop-color="${c[2]}"/></linearGradient>`;
    if (kind === 2) s += `<radialGradient id="g-${k}" cx=".34" cy=".28" r=".85"><stop offset="0" stop-color="${c[1]}"/><stop offset=".5" stop-color="${c[0]}"/><stop offset="1" stop-color="${c[2]}"/></radialGradient>`;
  }
  if (kind !== 1) s += '<filter id="halo" x="-20%" y="-20%" width="140%" height="140%"><feMorphology in="SourceAlpha" operator="dilate" radius="0.35"/><feGaussianBlur stdDeviation="0.5" result="b"/><feFlood flood-color="#0b0603" flood-opacity="0.85"/><feComposite in2="b" operator="in"/><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge></filter>';
  return s + '</defs>';
}
// The style handed to each drawing. The three kinds differ in the shape and hardness of light and shade:
// 1 soft: a slanted gradient, faint highlight and shade shapes;
// 2 glossy: light from the upper left as a round glow, strong highlights, bright glints, dark edge;
// 3 cut: flat colours with one hard light plane and one hard shadow plane, thick outline, dark edge.
function style(kind) {
  const o = { 1: [.34, .16], 2: [.62, .3], 3: [.5, .36] }[kind];
  const paint = c => kind === 3 ? PAL[c][0] : `url(#g-${c})`;
  return {
    kind, sw: { 1: 1, 2: 1.1, 3: 1.3 }[kind], f: paint,
    hi: d => `<path d="${d}" fill="#fff" opacity="${o[0]}" stroke="none"/>`,
    sh: d => `<path d="${d}" fill="#000" opacity="${o[1]}" stroke="none"/>`,
    glint: d => kind === 2 ? `<path d="${d}" fill="#fff" opacity=".9" stroke="none"/>` : '',
    // a line drawn as a dark outline with a coloured core (anchors, handles, the pound sign)
    pipe: (d, c, w) => `<path d="${d}" fill="none" stroke="${LINE}" stroke-width="${w + (kind === 3 ? 2.4 : 2)}" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="${paint(c)}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`
      + (kind === 3 ? `<path d="${d}" fill="none" stroke="#000" stroke-opacity=".3" stroke-width="${w * .36}" stroke-linecap="round" transform="translate(.4 .4)"/><path d="${d}" fill="none" stroke="#fff" stroke-opacity=".5" stroke-width="${w * .3}" stroke-linecap="round" transform="translate(-.4 -.4)"/>`
        : `<path d="${d}" fill="none" stroke="#fff" stroke-opacity="${kind === 2 ? .7 : .4}" stroke-width="${w * .28}" stroke-linecap="round" transform="translate(-.35 -.35)"/>`),
  };
}
function star(cx, cy, R, r) { let p = ''; for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, q = i % 2 ? r : R; p += (i ? 'L' : 'M') + (cx + q * Math.cos(a)).toFixed(2) + ' ' + (cy + q * Math.sin(a)).toFixed(2); } return p + 'Z'; }
function ear(t) { let s = ''; for (let y = 7; y < 20; y += 3.4) s += `<ellipse cx="10" cy="${y}" rx="1.9" ry="2.9" transform="rotate(-26 10 ${y})" fill="${t.f('gold')}"/><ellipse cx="14" cy="${y}" rx="1.9" ry="2.9" transform="rotate(26 14 ${y})" fill="${t.f('gold')}"/>`; return s + `<ellipse cx="12" cy="3.6" rx="1.9" ry="2.9" fill="${t.f('gold')}"/>`; }
function earA(t) { let s = ''; for (let y = 7; y < 20; y += 3.4) s += `<ellipse cx="10" cy="${y}" rx="1.9" ry="2.9" transform="rotate(-26 10 ${y})" fill="${t.f('amber')}"/><ellipse cx="14" cy="${y}" rx="1.9" ry="2.9" transform="rotate(26 14 ${y})" fill="${t.f('amber')}"/>`; return s + `<ellipse cx="12" cy="3.6" rx="1.9" ry="2.9" fill="${t.f('amber')}"/>`; }
const earAt = (t, deg) => `<g transform="rotate(${deg} 12 15.4) translate(12 15.4) scale(.6) translate(-12 -22)">${ear(t)}</g>`;

