function svgOf(icon, px) {
  const t = style(2);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-1.5 -1.5 27 27" width="${px}" height="${px}">${defs(2)}<g filter="url(#halo)" stroke="${LINE}" stroke-width="${t.sw}" stroke-linejoin="round">${icon.draw(t)}</g></svg>`;
}

// ---- batch 2 (2026-10-24): PLACEHOLDERS, drawn quickly so every good, pop type, alert, unit kind and
// building has a picture. Each entry carries `placeholder: true`: replace one by editing its entry here,
// or by dropping icons/<id>.svg in (see the top of this file). Same 24 x 24 box and glossy style.
Object.assign(PAL, {
  purple: ['#7a3aa8', '#d4a0ff', '#3a1260'], maroon: ['#8a3a22', '#d07a58', '#401408'],
});
// Another name for a drawn icon: the page asks for the key on the left, the drawing on the right is shown.
const ICON_ALIAS = {
  clergymen: 'clergy', telephone: 'telephones', clothes: 'regular_clothes', factory: 'industry',
  can_reform: 'reform', support: 'artillery', general: 'army', admiral: 'navy', diplo: 'diplopts',
};
// small drawing helpers for this batch
const rect = (x, y, w, h) => `M${x} ${y} L${x + w} ${y} L${x + w} ${y + h} L${x} ${y + h} Z`;
function gearPath(cx, cy, R, r, n) {
  let p = '';
  for (let k = 0; k < n; k++) {
    const a = k * 2 * Math.PI / n, w = Math.PI / n;
    [[a - w, r], [a - w * .55, R], [a + w * .55, R], [a + w, r]].forEach(([b, q], i) => { p += (k || i ? 'L' : 'M') + (cx + q * Math.cos(b)).toFixed(2) + ' ' + (cy + q * Math.sin(b)).toFixed(2); });
  }
  return p + 'Z';
}
function burst(cx, cy, R, r, n) { let p = ''; for (let i = 0; i < 2 * n; i++) { const a = -Math.PI / 2 + i * Math.PI / n, q = i % 2 ? r : R; p += (i ? 'L' : 'M') + (cx + q * Math.cos(a)).toFixed(2) + ' ' + (cy + q * Math.sin(a)).toFixed(2); } return p + 'Z'; }
